if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['customer_name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$carId=(int)($_POST['car_id']??0);$source=trim($_POST['source']??'');$dalaliId=(int)($_POST['dalali_id']??0);$min=(float)($_POST['budget_min']??0);$max=(float)($_POST['budget_max']??0);$next=$_POST['next_follow_up']?:null;$notes=trim($_POST['notes']??'');$uid=(int)$_SESSION['user_id'];if($name===''){$error='Customer name is required.';}else{$customerId=find_or_create_customer($conn,$name,$phone,$email,$uid);$st=$conn->prepare('INSERT INTO leads(customer_id,car_id,customer_name,phone,email,source,dalali_id,budget_min,budget_max,lead_stage,next_follow_up,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,\'NEW\',?,?,?)');$nullCar=$carId?:null;$nullDalali=$dalaliId?:null;$minv=$min?:null;$maxv=$max?:null;$st->bind_param('iissssiddssi',$customerId,$nullCar,$name,$phone,$email,$source,$nullDalali,$minv,$maxv,$next,$notes,$uid);if($st->execute()){$leadId=(int)$st->insert_id;if($dalaliId){$r=$conn->prepare('INSERT INTO dalali_referrals(dalali_id,lead_id,customer_id,car_id,notes) VALUES(?,?,?,?,?)');$r->bind_param('iiiis',$dalaliId,$leadId,$customerId,$nullCar,$notes);$r->execute();}car_sales_audit($conn,'CREATE','lead',$leadId,'Added sales lead for '.$name.'.',null,['customer_id'=>$customerId,'car_id'=>$nullCar,'dalali_id'=>$nullDalali,'source'=>$source,'budget_min'=>$minv,'budget_max'=>$maxv,'next_follow_up'=>$next]);set_flash('success','Sales lead added.');redirect_to('backend/leads/index.php');}else{$error='Could not add lead.';}}}
